'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/',U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P15_OUT||'P15_cleanup_output'),SHOTS=path.join(OUT,'P15_screenshots');fs.mkdirSync(SHOTS,{recursive:true});
const COMPANY=27,DUPLICATE=26,OWNER='p14_owner_260804221827',TEMP='P15 DELETE TEMP рейс';
function creds(){const e=process.env.P15_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return creds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function login(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(450);ok=!/\/login(?:[/?#]|$)/.test(p.url())}catch{}return{c,p,ok}}
function candidates(t,v){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==OWNER&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function owner(b){const s=sa(),x=await login(b,s.username,s.password);if(!x.ok)throw Error('superadmin login failed');await x.p.goto(U(`superadmin/companies/${COMPANY}/users`),{waitUntil:'domcontentloaded'});const f=x.p.locator(`form[action$="/superadmin/companies/${COMPANY}/owner/reset-password"]`).first(),n=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const vals=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(y=>y.value||y.textContent||'').filter(Boolean)),list=candidates(await x.p.locator('body').innerText(),vals);await x.c.close();for(const q of list){const y=await login(b,OWNER,q);if(y.ok)return y;await y.c.close()}throw Error('owner login failed')}
async function fill(f,n,v){const x=f.locator(`[name="${n}"]`).first();if(!(await x.count()))return;const tag=await x.evaluate(e=>e.tagName);if(tag==='SELECT')await x.evaluate((e,val)=>{const o=[...e.options].find(x=>String(x.value)===String(val));if(o){e.value=o.value;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}))}},String(v));else await x.fill(String(v))}
(async()=>{const r={status:'FAIL',route:{id:null,created:false,deleted:false,deletedDataVisible:false,restoreSupported:false},duplicateTenant:{id:DUPLICATE,archiveFormFound:false,archived:false,workingTenantStillActive:false},consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],error:null};let b,o;try{b=await chromium.launch({headless:true});o=await owner(b);const p=o.p;p.on('console',m=>{if(m.type()==='error')r.consoleErrors.push(m.text())});p.on('pageerror',e=>r.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>r.requestFailures.push(q.url()));p.on('response',z=>{if(z.status()>=500)r.httpFailures.push({status:z.status(),url:z.url()})});await p.goto(U('company/trips/linear'),{waitUntil:'networkidle'});let row=p.locator('tr[data-linear-route-id]').filter({hasText:TEMP}).first();if(!(await row.count())){await p.goto(U('company/trips/linear?show_create=1'),{waitUntil:'domcontentloaded'});const f=p.locator('#linear-trip-create-form');await fill(f,'route_type','linear');await fill(f,'planned_loading_date','15.08.2026');await fill(f,'client_id','1');await fill(f,'carrier_contractor_id','1');await fill(f,'route_executor_id','1');await fill(f,'cargo_type_name',TEMP);await fill(f,'customer_payments[0][amount]','1000');await fill(f,'customer_payments[0][payment_method]','cashless');await fill(f,'customer_payments[0][condition_type]','specific_date');await fill(f,'customer_payments[0][specific_due_date]','16.08.2026');await fill(f,'carrier_payments[0][amount]','500');await fill(f,'carrier_payments[0][payment_method]','cashless');await fill(f,'carrier_payments[0][condition_type]','after_end');await fill(f,'carrier_payments[0][days_count]','1');await fill(f,'carrier_payments[0][days_kind]','calendar');await f.evaluate(z=>z.requestSubmit());await p.waitForTimeout(1800);r.route.created=true;await p.goto(U('company/trips/linear'),{waitUntil:'networkidle'});row=p.locator('tr[data-linear-route-id]').filter({hasText:TEMP}).first()}await row.waitFor({state:'visible'});r.route.id=Number(await row.getAttribute('data-linear-route-id'));await row.dblclick();await p.locator('[data-linear-trip-delete-btn]').waitFor({state:'visible'});p.once('dialog',d=>d.accept());await p.locator('[data-linear-trip-delete-btn]').click();await p.waitForTimeout(1200);await p.goto(U('company/trips/linear'),{waitUntil:'networkidle'});r.route.deleted=(await p.locator('tr[data-linear-route-id]').filter({hasText:TEMP}).count())===0;await p.screenshot({path:path.join(SHOTS,'P15_011_OWNER_trip_soft_deleted_1920x1080.png'),fullPage:false});await o.c.close();o=null;
const s=sa(),admin=await login(b,s.username,s.password);if(!admin.ok)throw Error('second superadmin login failed');await admin.p.goto(U('superadmin/deleted-data'),{waitUntil:'domcontentloaded'});const deletedText=await admin.p.locator('body').innerText();r.route.deletedDataVisible=deletedText.includes(TEMP)||deletedText.includes(String(r.route.id));r.route.restoreSupported=await admin.p.locator('form,button,a').filter({hasText:/Восстановить/i}).count()>0;await admin.p.goto(U(`superadmin/companies/${DUPLICATE}`),{waitUntil:'domcontentloaded'});const detail=await admin.p.locator('body').innerText();if(!detail.includes('UIUX TEST EXPEDITOR'))throw Error('duplicate tenant identity mismatch');const archive=admin.p.locator(`form[action$="/superadmin/companies/${DUPLICATE}/archive"]`).first();r.duplicateTenant.archiveFormFound=(await archive.count())>0;if(await archive.count()){const nav=admin.p.waitForNavigation({waitUntil:'domcontentloaded'});await archive.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await nav;await admin.p.waitForTimeout(400)}await admin.p.goto(U('superadmin/companies'),{waitUntil:'domcontentloaded'});const rows=admin.p.locator('tbody tr');const dupRow=rows.filter({hasText:'UIUX TEST EXPEDITOR'}).filter({has:admin.p.locator(`a[href*="/superadmin/companies/${DUPLICATE}"]`)}).first();const dupText=await dupRow.innerText().catch(()=>'');r.duplicateTenant.archived=/Архив|archived/i.test(dupText)||(await admin.p.goto(U(`superadmin/companies/${DUPLICATE}`),{waitUntil:'domcontentloaded'}),/Архив|archived/i.test(await admin.p.locator('body').innerText()));await admin.p.goto(U(`superadmin/companies/${COMPANY}`),{waitUntil:'domcontentloaded'});r.duplicateTenant.workingTenantStillActive=/Актив|active/i.test(await admin.p.locator('body').innerText());await admin.p.screenshot({path:path.join(SHOTS,'P15_012_SUPERADMIN_duplicate_tenant_archived_1920x1080.png'),fullPage:false});await admin.c.close();r.status=r.route.deleted&&r.duplicateTenant.archiveFormFound&&r.duplicateTenant.archived&&r.duplicateTenant.workingTenantStillActive&&r.pageErrors.length===0&&r.requestFailures.length===0&&r.httpFailures.length===0?'PASS':'FAIL'}catch(e){r.error={name:e.name||'Error',message:String(e.message||e).slice(0,800)}}finally{if(o?.c)await o.c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P15_CLEANUP_RUNTIME.json'),JSON.stringify(r,null,2));console.log('P15_CLEANUP='+r.status);process.exitCode=r.status==='PASS'?0:1}})();
